/// <summary>
/// Initializes a new instance of the <see cref="OMGApplicationInsightsMessageSizeProperty"/> class.
/// </summary>
/// <param name="_size">Message size</param>
/// <returns>OMGApplicationInsightsMessageSizeProperty</returns>
public static OMGApplicationInsightsMessageSizeProperty newFromMessageSize(int64 _size)
{
    return new OMGApplicationInsightsMessageSizeProperty(int642Str(_size));
}
